const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const base=path.resolve(__dirname,'..'),src='step24-goal-trace-aaaed8d0-20260908.json';
const r=JSON.parse(fs.readFileSync(path.join(base,'reports/iteration',src)));
const catalogContext={};require('node:vm').runInNewContext(fs.readFileSync(path.join(base,'randomizer/game/card-catalog.js'),'utf8'),catalogContext);
assert.ok(r.passed&&r.actionMatches&&Object.values(r.parity).every(Boolean));
const rows=r.rows.filter(x=>x.strategic);assert.equal(rows.length,4096);
const nodes=new Map();
function ensure(p){const k=JSON.stringify(p);if(!nodes.has(k))nodes.set(k,{path:p,ids:new Set(),shared:new Set()});return nodes.get(k);}
for(const c of r.diagnostics.goalClusters||[])ensure(c.path);
const data=rows.map(row=>{
  const keys=new Set();
  for(const o of row.node.origins)if(o.target)for(const p of o.goalPaths||[])keys.add(JSON.stringify([...p,o.target]));
  for(const k of keys){const n=ensure(JSON.parse(k));n.ids.add(row.ordinal);if(keys.size>1)n.shared.add(row.ordinal);}
  return {id:row.ordinal,action:row.node.action.summary,before:row.node.priority,after:row.execution.priority,inputs:row.execution.inputs,keys:[...keys],origins:row.node.origins};
});
const payload={nodes:[...nodes.values()].map(n=>({...n,ids:[...n.ids],shared:n.shared.size,routes:(r.diagnostics.goalClusters||[]).find(c=>JSON.stringify(c.path)===JSON.stringify(n.path))?.routeVariants||[]})),rows:data,pending:r.diagnostics.frontierNodeBreakdown,remaining:r.diagnostics.remainingFrontierNodeCount,beam:r.diagnostics.beamPrunedOriginCount};
payload.cards=Object.fromEntries(catalogContext.SetiCardCatalog.map(c=>[c.card_id,{name:c.card_name,image:'../../assets/cards/'+c.set+'/split/'+c.card_id}]));
const initial=JSON.parse(fs.readFileSync(path.join(base,'reports/iteration/step24-initial-state-aaaed8d0-20260908.json')));
const initialState=typeof initial.state.committedState==='string'?JSON.parse(initial.state.committedState):initial.state.committedState;
payload.initial={player:initialState.players.players.find(p=>p.id==='player-white'),rockets:initialState.pieces.rockets.filter(p=>p.playerId==='player-white'),data:initial.observation.dataAnalyzeRequirements,probe:initial.observation.probeRouteRequirements,sector:initial.observation.sectorWinRequirements,tech:initial.observation.techGainRequirements,income:initial.observation.incomeGainRequirements};
const rootAnalysis=payload.nodes.find(n=>n.path.length===1&&n.path[0]==='data:analyze');
assert.deepEqual(rootAnalysis.routes[0].actions.map(a=>JSON.stringify(a)).sort(),rootAnalysis.routes[2].actions.map(a=>JSON.stringify(a)).sort());
rootAnalysis.routes[0].equivalentRouteNumbers=[1,3];rootAnalysis.routes[2].displayMergedInto=1;
const entryTrace=JSON.parse(fs.readFileSync(path.join(base,'reports/iteration/step24-entry-states-aaaed8d0-20260908.json')));
assert.ok(entryTrace.passed&&entryTrace.actionMatches&&Object.values(entryTrace.parity).every(Boolean));
const nodeByPath=new Map(payload.nodes.map(n=>[JSON.stringify(n.path),n]));
for(const n of payload.nodes)n.entries=[];
for(const row of entryTrace.rows.filter(r=>r.strategic)){
 for(const o of row.entryState.entryOrigins.filter(o=>o.target&&(o.entry||o.target.startsWith('decision:'))))for(const p of o.paths||[]){const n=nodeByPath.get(JSON.stringify([...p,o.target]));if(!n)continue;const player=row.entryState.player;const stateKey=JSON.stringify(player);let e=n.entries.find(e=>e.stateKey===stateKey);if(!e){e={stateKey,player,starts:[],ids:new Set(),masked:o.informationMasked};n.entries.push(e);}if(!e.starts.some(s=>JSON.stringify(s.chain)===JSON.stringify(o.chain)))e.starts.push({chain:o.chain,ordinal:row.ordinal});}
}
for(const row of entryTrace.rows.filter(r=>r.strategic))for(const o of row.entryState.entryOrigins.filter(o=>o.target))for(const p of o.paths||[]){const n=nodeByPath.get(JSON.stringify([...p,o.target]));if(!n)continue;for(const e of n.entries)if(e.starts.some(s=>s.chain.length<=o.chain.length&&s.chain.every((a,i)=>a===o.chain[i])))e.ids.add(row.ordinal);}
for(const n of payload.nodes)n.entries=n.entries.map(({stateKey,...e})=>({...e,ids:[...e.ids]}));
const html=`<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>第24步真实目标树</title><style>body{font:15px/1.6 system-ui;background:#f4f6fa;color:#223047;margin:24px}h1{font-size:26px}.note{background:#fff2cc;padding:14px}#layout{display:grid;grid-template-columns:minmax(380px,1fr) minmax(450px,1.3fr);gap:20px}section{background:white;padding:20px;border-radius:10px;overflow:auto;max-height:78vh}details{margin:8px 0 8px 16px;border-left:1px solid #abc;padding-left:12px}summary{cursor:pointer}button{cursor:pointer;color:#174d9f;background:#edf3ff;border:1px solid #bbcef0;border-radius:5px;margin-left:8px;padding:3px 8px}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #ddd;padding:8px;text-align:left;vertical-align:top}pre{white-space:pre-wrap;overflow-wrap:anywhere}.muted{color:#65748b}#tree{min-width:350px}@media(max-width:850px){#layout{display:block}section{margin-bottom:16px}} </style><h1>第24步：真实目标搜索树</h1><p>aaaed8d0 · 123.75基线 · 4096物理节点 / 6446规则输入 · 原记录分类与最终选择核对一致</p><p class="note">树节点表示“目标路径”，同一目标路径下不同状态和实现路线合并展示，不是单一游戏状态。节点数字为该路径<strong>自身执行的去重物理节点数</strong>，不含下属目标；一个物理执行可共享给多个目标，因此兄弟数字不能简单相加。点击“内部顺序”看真实全局序号及规则输入，不再把动作作为主树节点。</p><p><button id="expand">展开所有目标</button><button id="collapse">折叠</button><button id="all">全部4096节点顺序</button><a href="${src}">原始追踪JSON</a></p><div id="layout"><section><h2>目标树</h2><div id="tree"></div></section><section><h2 id="heading">节点内部展开顺序</h2><div id="detail"></div></section></div><section><h2>截断剩余</h2><p>剩余物理候选：${payload.remaining}；累计beam淘汰来源：${payload.beam}。后者不是独立物理节点数。待搜索节点没有完整路径身份，不能强行挂到树的某个父节点。</p><details><summary>待搜索队列原始明细</summary><pre id="pending"></pre></details></section><script id="data" type="application/json">${JSON.stringify(payload).replace(/</g,'\\u003c')}</script><script>
const D=JSON.parse(document.getElementById('data').textContent),byId=new Map(D.rows.map(r=>[r.id,r]));
const names={'data:analyze':'填数据／分析','land:mars:planet:':'登陆火星','orbit:mars:planet:':'环绕火星','orbit:venus:planet:':'环绕金星'};
const label=k=>names[k]||(k.startsWith('tech:gain:')?'获得科技 '+k.slice(10):k.startsWith('sector:win:')?'扫描取得扇区优势 '+k.slice(11):k.startsWith('income:gain:')?'获得收入 '+k.slice(12):k);
const el=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
const cardText=s=>String(s).replace(/(?:b_[0-9]+[.]webp|dlc_[0-9]+[.]png)/g,id=>D.cards[id]?.name||id);
const priorityNames=['是否完成绑定目标','填数据与探测器目标进度','当前状态价值','当前行动关联目标分数','探测器资源缺口缩小','新增外星人痕迹','数据数量缺口缩小','新增已填数据','分析就绪且有能量','最佳探测器目标分数','剩余移动步数的负值'];
function priorityTable(r){const box=el('div'),before=Array.isArray(r.before?.sortKey)?r.before.sortKey:[Number(r.before)||0],after=Array.isArray(r.after?.sortKey)?r.after.sortKey:[Number(r.after)||0];box.append(el('p','优先级按下列顺序逐项比较，先看前项，前项相同才比较下一项；不是加总得分。动作执行前的优先级继承自父状态。'));const table=el('table'),head=el('tr');['排序依据','执行前','执行后','变化'].forEach(t=>head.append(el('th',t)));table.append(head);let marked=false;priorityNames.forEach((name,i)=>{const a=before[i]||0,b=after[i]||0,tr=el('tr');if(a!==b&&!marked){tr.style.background='#fff2cc';name+='（首个变化项）';marked=true;}[name,a,b,b-a].forEach(v=>tr.append(el('td',String(v))));table.append(tr);});box.append(table);return box;}
function readableAction(a){const item=el('div',cardText(a.summary||a.family));for(const id of [...new Set(String(a.summary||'').match(/(?:b_[0-9]+[.]webp|dlc_[0-9]+[.]png)/g)||[])]){const c=D.cards[id];if(!c)continue;const link=el('a'),img=el('img');link.href=c.image;link.target='_blank';img.src=c.image;img.alt=c.name;img.loading='lazy';img.style.cssText='display:block;width:150px;max-width:100%;margin:8px 0';link.append(img);item.append(link);}return item;}
function goalDescription(n){const target=n.path.at(-1),I=D.initial,box=el('div');box.append(el('h3','进入这个目标时的真实状态'));if(!n.entries.length)box.append(el('p','未捕获已执行的目标起步状态；不使用整局初始状态代替。'));else{const table=el('table'),head=el('tr');['入口','钱','电','宣传','数据池','计算机','手牌数','关联执行节点'].forEach(t=>head.append(el('th',t)));table.append(head);n.entries.forEach((e,i)=>{const p=e.player,r=p.resources,tr=el('tr');['入口'+(i+1),r.credits,r.energy,r.publicity,r.availableData,p.dataState.placedTokens.length+'/6',p.hand.length,e.ids.length].forEach(v=>tr.append(el('td',String(v))));table.append(tr);});box.append(table,el('p','按完整玩家状态分组；表中钱、电等相同的入口仍可能有不同手牌或科技。关联节点按该入口前置动作链的延续匹配，同一执行可能归属多个入口，不能相加。'));n.entries.forEach((e,i)=>{const d=el('details');d.append(el('summary','入口'+(i+1)+'：手牌、科技与起步序号'));const p=e.player;d.append(el('p','起步全局序号：'+e.starts.map(s=>'#'+s.ordinal).join('、')+'；科技：'+(Object.keys(p.techState.ownedTiles).join('、')||'无')));for(const c of p.hand)d.append(readableAction({summary:c.cardId}));box.append(d);});}box.append(el('h3','目标说明（以下根盘面参考不替代上表入口状态）'));
if(target==='data:analyze')box.append(el('p','补齐数据、填满计算机并执行分析。各入口的剩余数据缺口：'+n.entries.map((e,i)=>'入口'+(i+1)+'缺'+Math.max(0,6-e.player.dataState.placedTokens.length-e.player.resources.availableData)+'个').join('；')+'。第4格有收入奖励，不等于6格填满。'));
else if(target.startsWith('income:gain:'))box.append(el('p','通过指定路线推进收入目标。初始永久收入为4钱、2电、1张牌及1次额外公共扫描；起点可选路线包含填到计算机第4格并选择收入牌，以及行星环绕。目标编号里的数字是收入基线，不是奖励数量。'));
else if(target.startsWith('tech:gain:')){const t=I.tech.plans.find(t=>t.targetId===target);box.append(el('p','获得 '+label(target)+' 对应的科技板块。全搜索起点宣传4，正式研究需求'+I.tech.researchCost+'宣传'+(t?'，初始缺'+t.gap.publicity+'宣传':'')+'；目前没有已拥有科技。'));
}else if(target.startsWith('sector:win:')){const s=I.sector.candidates.find(s=>s.targetId===target);box.append(el('p',s?'在指定扇区下一次结算时取得优势。初始自己的标记'+s.ownCount+'，对手最多'+s.maxOpponentCount+'，剩余空槽'+s.openSlotCount+'；目录计算需自己的标记'+s.minimumOwnMarks+'。标准扫描费用1钱2电。':'取得目标扇区的下一次结算优势；该目标的进入状态不能由初始盘面代替。'));
}else{const p=I.probe.candidates.find(p=>p.targetId===target);box.append(el('p',p?'让探测器完成'+label(target)+'。初始无白方在场探测器，普通路线从发射开始；目录需求'+p.required.credits+'钱、'+p.required.energy+'电、移动'+p.required.movementSteps+'步。收益：'+p.targetBenefit.rewardSummary:'完成当前挂起的目标选择或后续目标，具体选项与效果见下方执行路线。'));}return box;}
function show(n){document.getElementById('heading').textContent=n?n.letter+'：'+n.path.map(label).join(' → '):'全部4096节点的实际顺序';const box=document.getElementById('detail');box.replaceChildren();const ids=n?n.ids:D.rows.map(r=>r.id);if(n)box.append(goalDescription(n));
if(n){box.append(el('h3','如何达成这个目标'));if(n.path.length===1&&n.path[0]==='data:analyze')box.append(el('p','审查结论：收入盲抽缺少隐藏信息屏障，霍尔效应推进器不应提前用于规划。路线2的扫描本身给2数据，不弃霍尔也能填满；路线1与3只交换两张弃牌顺序，已合并展示，实际搜索计数保留。'));if(!n.routes.length)box.append(el('p','本次没有记录到完成该目标的路线，不能虚构成功链。'));n.routes.forEach((route,i)=>{if(route.displayMergedInto)return;const d=el('details'),s=el('summary','路线'+(i+1)+(route.equivalentRouteNumbers?'（合并原路线3）':'')+'：'+route.actions.map(a=>cardText(a.summary||a.family)).join(' → '));d.append(s);if(route.equivalentRouteNumbers)d.append(el('p','原路线3仅交换霍尔与DLC9弃牌换数据的顺序，按用户裁定折叠。原始日志及物理搜索计数没有删除。'));const list=el('ol');route.actions.forEach(a=>{const li=el('li');li.append(readableAction(a));list.append(li);});d.append(list);box.append(d);});}
box.append(el('h3','搜索实际按什么顺序展开'));box.append(el('p','共 '+ids.length+' 个物理执行。以下是多条候选路线交替展开的顺序，不是一条行动计划。序号跳跃表示期间执行了其他目标；每行展开看卡图、正式输入及优先级变化。'));const table=el('table');for(const id of ids){const r=byId.get(id),tr=el('tr');tr.append(el('td','#'+id));const td=el('td'),d=el('details'),sum=el('summary',cardText(r.action)+' · '+(r.inputs||[]).length+'次输入');d.append(sum);d.addEventListener('toggle',()=>{if(!d.open||d.dataset.loaded)return;d.dataset.loaded='1';d.append(priorityTable(r));const list=el('ol');(r.inputs||[]).forEach(a=>{const li=el('li');li.append(readableAction(a));list.append(li);});d.append(list);const raw=el('details');raw.append(el('summary','技术附录（可忽略）'));raw.append(el('pre',JSON.stringify({来源与前置动作链:r.origins},null,2)));d.append(raw);});td.append(d);tr.append(td);table.append(tr);}box.append(table);}
const children=new Map();for(const n of D.nodes){const k=JSON.stringify(n.path.slice(0,-1));if(!children.has(k))children.set(k,[]);children.get(k).push(n);}
const pathNodes=new Map(D.nodes.map(n=>[JSON.stringify(n.path),n]));let serial=0;function letters(i){let s='';for(i++;i>0;i=Math.floor((i-1)/26))s=String.fromCharCode(65+(i-1)%26)+s;return s;}
const initialPanel=el('section');initialPanel.style.maxHeight='none';initialPanel.append(el('h2','第24步搜索开始前：白方准备状态'));const P=D.initial.player,R=P.resources;initialPanel.append(el('p','分数 '+R.score+' ｜ 钱 '+R.credits+' ｜ 电 '+R.energy+' ｜ 宣传 '+R.publicity+' ｜ 可用数据 '+R.availableData+' ｜ 手牌 '+P.hand.length+'张'));initialPanel.append(el('p','计算机：'+Array.from({length:6},(_,i)=>'['+(i+1)+'：'+(i<D.initial.data.computerPlacedCount?'已填':'空')+']').join(' ')+'；共6格，当前全部为空。'));initialPanel.append(el('p','可用数据池：'+D.initial.data.availableData+'个。填满6格还需获取'+D.initial.data.dataNeeded+'个；现有4个只能填到第4格，不能填满6格。'));initialPanel.append(el('p','公司：深空探测 ｜ 在场探测器：'+D.initial.rockets.length+'艘 ｜ 已拥有科技：'+Object.keys(P.techState.ownedTiles).length+'个'));const hand=el('div');hand.style.cssText='display:flex;gap:20px;flex-wrap:wrap';for(const c of P.hand)hand.append(readableAction({summary:c.cardId}));initialPanel.append(el('h3','初始手牌'),hand);const source=el('a','初始状态证据（仅重放正式动作，没有再次搜索）');source.href='step24-initial-state-aaaed8d0-20260908.json';initialPanel.append(source);document.getElementById('layout').before(initialPanel);
const ordered=[...D.nodes].sort((a,b)=>a.path.length-b.path.length||b.ids.length-a.ids.length);for(const n of ordered)n.letter=letters(serial++);
const tree=document.getElementById('tree');tree.append(el('p','每层列出该层所有目标；“父X”表示从哪个上一层目标完成后继续搜索。数字仅为达成当前目标的搜索成本，不含下一层。'));
for(let depth=1;depth<=Math.max(...D.nodes.map(n=>n.path.length));depth++){const group=el('details');group.open=depth<=2;group.append(el('summary','第'+depth+'层目标'));for(const n of ordered.filter(n=>n.path.length===depth)){const parent=pathNodes.get(JSON.stringify(n.path.slice(0,-1))),card=el('p');const button=el('button',n.letter+' '+label(n.path.at(-1))+' ｜ '+n.ids.length+'节点');button.onclick=()=>show(n);card.append(button,el('span',' ← '+(parent?'父'+parent.letter:'起点')+' · 共享'+n.shared));group.append(card);}tree.append(group);}
document.getElementById('expand').onclick=()=>document.querySelectorAll('#tree details').forEach(d=>d.open=true);document.getElementById('collapse').onclick=()=>document.querySelectorAll('#tree details').forEach(d=>d.open=false);document.getElementById('all').onclick=()=>show(null);document.getElementById('pending').textContent=JSON.stringify(D.pending,null,2);show(ordered[0]);
</script></html>`;
const out=path.join(base,'reports/iteration/step24-real-goal-tree-aaaed8d0-20260908-v9.html');
if(fs.existsSync(out)){assert.equal(fs.readFileSync(out,'utf8'),html);console.log('已有一致报告，跳过');}else fs.writeFileSync(out,html,{flag:'wx'});
